/*
 * area_$free_segments - release the pages [start, end] of an area
 *
 * Original address: 0x00E085A6 (module-local; the SAU2 map has no symbol
 * here, Ghidra carries the tree name)
 * Size: 532 bytes (0x00E085A6 .. 0x00E087B9), plus its nested procedure
 * area_$free_slot_segments at 0x00E082A8 (766 bytes; was Ghidra FUN_00e082a8)
 * Generated by: Claude Opus 5.5
 *
 * Callers: area_$resize (0x00E0893C) and AREA_$INVALIDATE (0x00E08F1E,
 * 0x00E08F6C, 0x00E08FD8); A5 = 0xE1E118 (AREA_$GLOBALS) is the caller's.
 *
 * Frame (link.w A6,-0xb4; D2-D7/A2 saved):
 *   (0x08,A6) area_id   word
 *   (0x0A,A6) start     longword page number (0x00E085D4)
 *   (0x0E,A6) end       longword page number (0x00E085DE)
 *   (0x12,A6) clear     byte (`tst.b (0x12,A6)`): also forget the segments
 *   (0x14,A6) status_p
 *   (-0x80)   bat_list  disk blocks to give back, Pascal [1..31]: element i
 *                       at (-0x84 + i*4) (0x00E084BA)
 *   (-0x88)   prev      the overflow table before the current one
 *   (-0x90)   entry     the area entry
 *   (-0x92)   bat_count
 *   (-0x94)   last table index; (-0x98) last cell in the table;
 *   (-0xa4)   last_seg = end >> 5; (-0xa6) first_seg = start >> 5
 *   (-0xa8)   a word the parent counts through its cells and the nested
 *             procedure reuses as its RPMAP-cache index; nothing reads the
 *             parent's value
 *   (-0xaa)   table loop counter; (-0xb0)/(-0xb4) first/last cell - 2
 * All of it but (-0x88)..(-0x98) and the counters is read by the nested
 * procedure through its static link, so the C passes the frame record.
 *
 * Blocks (parent):
 *   0x00E085AE-0x00E085F2  *status := 0; bat_count := 0; entry; first/last
 *                          segment and their slot cells n = seg >> 3
 *   0x00E085F4-0x00E08628  cells 0 and 1 (inline in the entry,
 *                          entry->seg_bitmap) from first n to min(1, last n)
 *   0x00E0862C-0x00E0865A  cells from max(first n, 2): overflow tables
 *                          (n - 2) >> 8 .. (last n - 2) >> 8
 *   0x00E08662-0x00E086E8  per table: first/last cell ((n - 2) mod 0x100,
 *                          M$OIS$WLW), find it on seg_table_list[owner_asid]
 *                          (none -> CRASH_SYSTEM(Area_Internal_Error))
 *   0x00E086EA-0x00E0871C  its cells first..last through the nested procedure
 *   0x00E08720-0x00E0876A  a table entered at cell 0 with `clear' set is
 *                          freed (area_$free_seg_table) - for the first
 *                          table only when start <= 0x200 or
 *                          (start - 0x200) mod 0x100 = 0
 *   0x00E08778-0x00E087AA  bat_count <> 0: BAT_$FREE(bat_list, bat_count,
 *                          entry->volx, 0, status); failure -> CRASH_SYSTEM
 */

#include "area/area_internal.h"
#include "ast/ast.h"
#include "bat/bat.h"
#include "dbuf/dbuf.h"
#include "misc/crash_system.h"

/* `cmpi.w #0x2,D3w` 0x00E085F4: cells 0 and 1 live in the entry */
#define AREA_FS_INLINE_CELLS    2
/* `move.w #0x100,-(SP)` 0x00E0866C: cells per overflow table */
#define AREA_FS_CELLS_PER_TABLE 0x100
/* `cmpi.w #0x1f,(-0x92,A4)` 0x00E084DE: bat_list is [1..31] */
#define AREA_FS_BAT_MAX         0x1F
/* `cmpi.l #0x200,(0xa,A6)` 0x00E0872E */
#define AREA_FS_FIRST_TABLE_PAGE 0x200
/* `moveq #0x2,D0` + dbf 0x00E08540: the three RPMAP cache slots */
#define AREA_FS_RPMAP_SLOTS     3

/* The parent's frame as the nested procedure reaches it through (A6). */
typedef struct area_$free_segs_frame_t {
    int16_t         area_id;        /* (0x08,A6) */
    uint32_t        start;          /* (0x0A,A6) */
    uint32_t        end;            /* (0x0E,A6) */
    int8_t          clear;          /* (0x12,A6) */
    status_$t      *status_p;       /* (0x14,A6) */
    area_$entry_t  *entry;          /* (-0x90,A6) */
    uint16_t        first_seg;      /* (-0xa6,A6) */
    uint16_t        last_seg;       /* (-0xa4,A6) */
    uint16_t        cell_counter;   /* (-0xa8,A6) */
    uint16_t        bat_count;      /* (-0x92,A6) */
    uint32_t        bat_list[AREA_FS_BAT_MAX + 1]; /* (-0x84,A6): [0] is the
                                     * bias slot, [1..31] at (-0x80..-0x8) */
} area_$free_segs_frame_t;

/*
 * area_$free_slot_segments - nested procedure 0x00E082A8 (766 bytes)
 *
 * Releases the segments of one slot cell (the group of eight segments
 * n*8 .. n*8+7) that fall inside [first_seg, last_seg].  Frame (link.w
 * A6,-0x24): (0x08) slot -> D7, (0x0C) n word -> D3w; A4 = the parent's A6
 * (`movea.l (A6),A4`).  The caller pushes a result slot it never reads.
 *
 *   0x00E082BA-0x00E082DA  D4w := max(n*8, first_seg) (unsigned `bhi`);
 *                          D2 := min(last_seg, n*8 + 7) (signed long `ble`)
 *   0x00E082DC-0x00E082E6  local := (entry->remote_volx = 0) (`seq`)
 *   0x00E082EA-0x00E0830C  ML_$LOCK(0x12); wait out and then set the slot's
 *                          in-transition bit
 *   0x00E08312-0x00E0847C  if any bit is set, segments D4..D2: for each
 *                          allocated one, the page range inside it (first
 *                          page from start, last from end, else 0 / 0x1F),
 *                          area_$get_aste(.., held TRUE, create = local):
 *                          0x30004 = nothing active (status cleared, the
 *                          bit dropped when clearing from page 0); other
 *                          errors CRASH_SYSTEM(Area_Internal_Error); else
 *                          unlock, AST_$FREE_PAGES, relock, and when
 *                          clearing from page 0 drop the bit, unchain the
 *                          ASTE from the slot (a sole ASTE hands its block
 *                          address back to the cell) and AST_$FREE_ASTE it,
 *                          otherwise wire_count -= 1
 *   0x00E08480-0x00E08582  clearing, no bit left and a block address in the
 *                          cell: local - queue it on bat_list,
 *                          DBUF_$INVALIDATE it and flush at 31 with
 *                          BAT_$FREE (unlocked; failure -> CRASH_SYSTEM);
 *                          remote - forget the RPMAP cache slot holding
 *                          this group; then clear the address
 *   0x00E08588-0x00E08596  clear the in-transition bit; ML_$UNLOCK(0x12)
 */
static void area_$free_slot_segments(area_$free_segs_frame_t *up,
                                     area_$seg_slot_t *slot, uint16_t n)
{
    area_$entry_t *entry = up->entry;
    aste_t *aste;                   /* A3 */
    aste_t *link;                   /* A2 */
    uint16_t seg;                   /* D4w */
    uint16_t remaining;             /* D2w */
    uint16_t bit;                   /* D5w */
    uint16_t first_page;            /* D6w */
    uint16_t last_page;             /* (-0x1a,A6) */
    uint32_t hi;                    /* D2 */
    uint32_t daddr;                 /* D0 */
    int8_t local;                   /* (-0x1e,A6) */
    area_$rpmap_cache_t *c;

    /* 0x00E082BA-0x00E082C6 */
    seg = (uint16_t)(n << 3);
    if (!(seg > up->first_seg)) {
        seg = up->first_seg;
    }
    /* 0x00E082CA-0x00E082DA */
    hi = up->last_seg;
    if (!((int32_t)hi <= (int32_t)((uint32_t)(uint16_t)(n << 3) + 7))) {
        hi = (uint32_t)(uint16_t)(n << 3) + 7;
    }

    /* 0x00E082DC-0x00E082E6 */
    local = (entry->remote_volx == 0) ? -1 : 0;

    /* 0x00E082EA-0x00E0830C */
    ML_$LOCK(ML_LOCK_AST);
    while ((slot->state & AREA_SLOT_IN_TRANS) != 0) {
        area_$wait_pite_in_trans();
    }
    slot->state |= AREA_SLOT_IN_TRANS;

    /* 0x00E08312-0x00E08322 */
    if (slot->bits != 0 && !((uint16_t)hi < seg)) {
        remaining = (uint16_t)((uint16_t)hi - seg);
        do {
            /* 0x00E08324-0x00E08330 */
            bit = seg & 7;
            if (((slot->bits >> bit) & 1) != 0) {
                /* 0x00E08334-0x00E0835A */
                first_page = (seg == up->first_seg) ? (uint16_t)(up->start & 0x1F) : 0;
                last_page = (seg == up->last_seg) ? (uint16_t)(up->end & 0x1F) : 0x1F;

                /* 0x00E0835C-0x00E08376 */
                aste = area_$get_aste(up->area_id, slot, (int16_t)seg, -1, local,
                                      up->status_p);

                if (*up->status_p == status_$ast_segment_not_deactivatable) {
                    /* 0x00E08384-0x00E083A6 */
                    *up->status_p = status_$ok;
                    if (up->clear < 0 && first_page == 0) {
                        slot->bits = (uint8_t)(slot->bits & ~(1u << bit));
                    }
                } else {
                    /* 0x00E083AA-0x00E083BC */
                    if (*up->status_p != status_$ok) {
                        CRASH_SYSTEM(&Area_Internal_Error);
                    }

                    /* 0x00E083BE-0x00E083F4 */
                    ML_$UNLOCK(ML_LOCK_AST);
                    AST_$FREE_PAGES(aste, (int16_t)first_page, (int16_t)last_page,
                                    entry->volx);
                    ML_$LOCK(ML_LOCK_AST);

                    if (up->clear < 0 && first_page == 0) {
                        /* 0x00E08400-0x00E0840C */
                        slot->bits = (uint8_t)(slot->bits & ~(1u << bit));

                        /* 0x00E0840E-0x00E08468 */
                        link = AST_ASTE_ENTRY(slot->aste_index);
                        if (link == aste) {
                            if (aste->next == NULL) {
                                /* 0x00E0842C-0x00E08440 */
                                slot->state &= (uint8_t)~AREA_SLOT_HAS_ASTE;
                                AREA_SLOT_STORE(slot,
                                    (AREA_SLOT_LONG(slot) & ~AREA_SLOT_DADDR_MASK) |
                                    (aste->fm_block >> 4));
                            } else {
                                /* 0x00E08444-0x00E08448 */
                                slot->aste_index = aste->next->seg_index;
                            }
                        } else {
                            /* 0x00E08450-0x00E08468 */
                            while (link->next != aste) {
                                link = link->next;
                                if (link == NULL) {
                                    CRASH_SYSTEM(&Area_Internal_Error);
                                }
                            }
                            link->next = aste->next;
                        }

                        /* 0x00E0846A-0x00E08472 */
                        AST_$FREE_ASTE(aste);
                    } else {
                        /* 0x00E08476 */
                        aste->wire_count--;
                    }
                }
            }
            /* 0x00E0847A-0x00E0847C */
            seg++;
        } while (remaining-- != 0);
    }

    /* 0x00E08480-0x00E0849C */
    if (up->clear < 0 && slot->bits == 0 &&
        (daddr = AREA_SLOT_LONG(slot) & AREA_SLOT_DADDR_MASK) != 0) {
        if (entry->remote_volx == 0) {
            /* 0x00E084AC-0x00E084DC */
            up->bat_count++;
            up->bat_list[up->bat_count] = daddr;
            DBUF_$INVALIDATE((int32_t)up->bat_list[up->bat_count],
                             (uint16_t)entry->volx);

            /* 0x00E084DE-0x00E0853A */
            if (!(up->bat_count < AREA_FS_BAT_MAX)) {
                ML_$UNLOCK(ML_LOCK_AST);
                BAT_$FREE(&up->bat_list[1], (int16_t)up->bat_count,
                          entry->volx, 0, up->status_p);
                ML_$LOCK(ML_LOCK_AST);
                if (*up->status_p != status_$ok) {
                    CRASH_SYSTEM(up->status_p);
                }
                up->bat_count = 0;
            }
        } else {
            /* 0x00E08540-0x00E0857E: (-0xa8) of the PARENT is the index */
            up->cell_counter = 1;
            for (c = &AREA_$GLOBALS.rpmap_cache[0];
                 up->cell_counter <= AREA_FS_RPMAP_SLOTS;
                 up->cell_counter++, c++) {
                if ((int16_t)c->word_04 == entry->remote_volx &&
                    c->word_06 == n) {
                    c->seq = 0;
                    c->word_04 = 0;
                    c->byte_08 = 0;
                    break;
                }
            }
        }

        /* 0x00E08582 */
        AREA_SLOT_STORE(slot, AREA_SLOT_LONG(slot) & ~AREA_SLOT_DADDR_MASK);
    }

    /* 0x00E08588-0x00E08596 */
    slot->state &= (uint8_t)~AREA_SLOT_IN_TRANS;
    ML_$UNLOCK(ML_LOCK_AST);
}

void area_$free_segments(int16_t area_id, uint32_t start_page,
                         uint32_t end_page, int8_t clear_bitmap,
                         status_$t *status_p)
{
    area_$free_segs_frame_t f;
    area_$seg_slot_t *cell;         /* A2 / D5 */
    area_$seg_table_t *tbl;         /* A2 */
    area_$seg_table_t *prev;        /* (-0x88,A6) */
    uint16_t first_n, last_n;       /* D3w, D4w */
    uint16_t n;                     /* D5w, then D2w */
    int16_t k;                      /* D2w / D4w dbf counters */
    int16_t hi;                     /* D0w */
    uint16_t first_tbl, last_tbl;   /* D3w, (-0x94,A6) */
    uint16_t tables_left;           /* (-0xaa,A6) */
    uint16_t t;                     /* D6w */
    uint16_t first_cell;            /* D7w */
    uint16_t last_cell;             /* (-0x98,A6) */
    int32_t first_cell_n;           /* (-0xb0,A6) */
    int32_t last_cell_n;            /* (-0xb4,A6) */

    f.area_id = area_id;
    f.start = start_page;
    f.end = end_page;
    f.clear = clear_bitmap;
    f.status_p = status_p;

    /* 0x00E085AE-0x00E085D0 */
    *status_p = status_$ok;
    f.bat_count = 0;
    f.entry = AREA_ID_TO_ENTRY((uint16_t)area_id);

    /* 0x00E085D4-0x00E085F2 */
    f.first_seg = (uint16_t)(start_page >> 5);
    f.last_seg = (uint16_t)(end_page >> 5);
    first_n = f.first_seg >> 3;
    last_n = f.last_seg >> 3;

    /* 0x00E085F4-0x00E08628: the two cells inside the entry */
    if ((int16_t)first_n < AREA_FS_INLINE_CELLS) {
        hi = 1;
        if (!(hi <= (int16_t)last_n)) {
            hi = (int16_t)last_n;
        }
        hi = (int16_t)(hi - (int16_t)first_n);
        if (hi >= 0) {
            n = first_n;
            k = hi;
            do {
                /* `lea (0x0,A1,D5w*4)` + `pea (0x18,A2)`: n is 0 or 1 */
                cell = (area_$seg_slot_t *)&f.entry->seg_bitmap[n];
                area_$free_slot_segments(&f, cell, n);
                n++;
            } while (--k != -1);
        }
    }

    /* 0x00E0862C-0x00E08630 */
    if ((int16_t)last_n < AREA_FS_INLINE_CELLS) {
        goto flush;
    }

    /* 0x00E08634-0x00E0865A */
    if ((int16_t)first_n < AREA_FS_INLINE_CELLS) {
        first_n = AREA_FS_INLINE_CELLS;
    }
    n = first_n;
    first_cell_n = (int32_t)(int16_t)first_n - AREA_FS_INLINE_CELLS;
    last_cell_n = (int32_t)(int16_t)last_n - AREA_FS_INLINE_CELLS;
    first_tbl = (uint16_t)((uint32_t)first_cell_n >> 8);
    last_tbl = (uint16_t)((uint32_t)last_cell_n >> 8);
    if ((int16_t)(last_tbl - first_tbl) < 0) {
        goto flush;
    }
    tables_left = (uint16_t)(last_tbl - first_tbl);

    t = first_tbl;
    do {
        /* 0x00E08664-0x00E0867C */
        first_cell = 0;
        if (t == first_tbl) {
            first_cell = (uint16_t)M$OIS$WLW(first_cell_n, AREA_FS_CELLS_PER_TABLE);
        }
        /* 0x00E0867E-0x00E0869C */
        last_cell = 0xFF;
        if (t == last_tbl) {
            last_cell = (uint16_t)M$OIS$WLW(last_cell_n, AREA_FS_CELLS_PER_TABLE);
        }

        /* 0x00E086A0-0x00E086D6 */
        tbl = AREA_$GLOBALS.seg_table_list[f.entry->owner_asid];
        prev = NULL;
        while (tbl != NULL) {
            if (tbl->area_id == area_id && (uint16_t)tbl->table_index == t) {
                break;
            }
            prev = tbl;
            tbl = (area_$seg_table_t *)ARCH_VA_TO_PTR(tbl->next);
        }
        /* 0x00E086D8-0x00E086E8 */
        if (tbl == NULL) {
            CRASH_SYSTEM(&Area_Internal_Error);
        }

        /* 0x00E086EA-0x00E0871C */
        cell = (area_$seg_slot_t *)((uint8_t *)ARCH_VA_TO_PTR(tbl->bitmap_ptr) +
               (int32_t)(int16_t)first_cell * 4);
        hi = (int16_t)(last_cell - first_cell);
        if (hi >= 0) {
            k = hi;
            f.cell_counter = first_cell;
            do {
                area_$free_slot_segments(&f, cell, n);
                cell++;
                n++;
                f.cell_counter++;
            } while (--k != -1);
        }

        /* 0x00E08720-0x00E0876A */
        if (first_cell == 0 && clear_bitmap < 0) {
            if ((int16_t)t > (int16_t)first_tbl ||
                !(start_page > AREA_FS_FIRST_TABLE_PAGE) ||
                M$OIS$WLW((long)(start_page - AREA_FS_FIRST_TABLE_PAGE),
                          AREA_FS_CELLS_PER_TABLE) == 0) {
                area_$free_seg_table(tbl, prev, f.entry->owner_asid);
            }
        }

        /* 0x00E0876E-0x00E08774 */
        t++;
    } while (tables_left-- != 0);

flush:
    /* 0x00E08778-0x00E087AA */
    if (f.bat_count != 0) {
        BAT_$FREE(&f.bat_list[1], (int16_t)f.bat_count, f.entry->volx, 0,
                  status_p);
        if (*status_p != status_$ok) {
            CRASH_SYSTEM(status_p);
        }
    }
}
